olor-id=\\"0\\"/>\\n                <we-colorpicker data-set-img-shape-color=\\"true\\" data-dependencies=\\"shape_img_opt\\" data-name=\\"img-shape-color-1\\" data-color-id=\\"1\\"/>\\n                <we-colorpicker data-set-img-shape-color=\\"true\\" data-dependencies=\\"shape_img_opt\\" data-name=\\"img-shape-color-2\\" data-color-id=\\"2\\"/>\\n                <we-colorpicker data-set-img-shape-color=\\"true\\" data-dependencies=\\"shape_img_opt\\" data-name=\\"img-shape-color-3\\" data-color-id=\\"3\\"/>\\n                <we-colorpicker data-set-img-shape-color=\\"true\\" data-dependencies=\\"shape_img_opt\\" data-name=\\"img-shape-color-4\\" data-color-id=\\"4\\"/>\\n            </we-row>\\n            <we-row string=\\"Transform\\" class=\\"o_we_sublevel_1\\">\\n                <we-button class=\\"oi oi-fw oi-arrows-h\\" data-name=\\"img_shape_transform_flip_x_opt\\" data-set-img-shape-flip-x=\\"true\\" data-no-preview=\\"true\\" data-dependencies=\\"shape_img_opt\\" title=\\"Horizontal mirror\\"/>\\n                <we-button class=\\"oi oi-fw oi-arrows-v\\" data-name=\\"img_shape_transform_flip_y_opt\\" data-set-img-shape-flip-y=\\"true\\" data-no-preview=\\"true\\" data-dependencies=\\"shape_img_opt\\" title=\\"Vertical mirror\\"/>\\n                <we-button class=\\"fa fa-fw fa-rotate-left\\" data-name=\\"img_shape_transform_rotate_x_opt\\" data-set-img-shape-rotate-left=\\"true\\" data-no-preview=\\"true\\" data-dependencies=\\"shape_img_opt\\" title=\\"Rotate left\\"/>\\n                <we-button class=\\"fa fa-fw fa-rotate-right\\" data-name=\\"img_shape_transform_rotate_y_opt\\" data-set-img-shape-rotate-right=\\"true\\" data-no-preview=\\"true\\" data-dependencies=\\"shape_img_opt\\" title=\\"Rotate right\\"/>\\n            </we-row>\\n        </div>\\n        <we-input string=\\"Description\\" class=\\"o_we_large\\" data-select-attribute=\\"\\" data-attribute-name=\\"alt\\" placeholder=\\"Alt tag\\" title=\\"'Alt tag' specifies an alternate text for an image, if the image cannot be displayed (slow connection, missing image, screen reader ...).\\"/>\\n        <we-input string=\\"Tooltip\\" class=\\"o_we_large\\" data-select-attribute=\\"\\" data-attribute-name=\\"title\\" placeholder=\\"Title tag\\" title=\\"'Title tag' is shown as a tooltip when you hover the picture.\\"/>\\n        <we-row string=\\"Transform\\">\\n            <we-button class=\\"fa fa-fw fa-crop\\" data-crop=\\"true\\" data-no-preview=\\"true\\" title=\\"Crop Image\\"/>\\n            <we-button class=\\"o_we_bg_danger ms-0 border-start-0\\" data-reset-crop=\\"\\" data-no-preview=\\"true\\" title=\\"Reset crop\\">\\n                Reset\\n            </we-button>\\n            <we-button class=\\"fa fa-fw fa-object-ungroup\\" data-name=\\"image_transform_opt\\" data-transform=\\"true\\" data-no-preview=\\"true\\" title=\\"Transform the picture\\"/>\\n            <we-button class=\\"ms-0 border-start-0\\" data-reset-transform=\\"\\" data-no-preview=\\"true\\" title=\\"Reset transformation\\">\\n                Reset\\n            </we-button>\\n        </we-row>\\n\\n        <t t-call=\\"web_editor.snippet_options_image_optimization_widgets\\"/>\\n\\n        <we-button-group string=\\"Size\\" data-css-property=\\"width\\">\\n            <we-button data-select-style=\\"\\" title=\\"Resize Default\\">Default</we-button>\\n            <we-button data-select-style=\\"25%\\" title=\\"Resize Quarter\\">25%</we-button>\\n            <we-button data-select-style=\\"50%\\" title=\\"Resize Half\\">50%</we-button>\\n            <we-button data-select-style=\\"100%\\" title=\\"Resize Full\\">100%</we-button>\\n        </we-button-group>\\n    </div>\\n\\n    <div data-selector=\\"span.fa, i.fa, img\\" data-exclude=\\"[data-oe-type='image'] &gt; img, [data-oe-xpath]\\" class=\\"o_we_image_options\\">\\n        <we-select string=\\"Alignment\\" data-state-to-first-class=\\"true\\">\\n            <we-button data-select-class=\\"\\" title=\\"Unalign\\">None</we-button>\\n            <we-button data-select-class=\\"me-auto float-start\\" title=\\"Align Left\\">Left</we-button>\\n            <we-button data-select-class=\\"mx-auto d-block\\" title=\\"Align Center\\">Center</we-button>\\n            <we-button data-select-class=\\"ms-auto float-end\\" title=\\"Align Right\\">Right</we-button>\\n        </we-select>\\n\\n        <we-row string=\\"Style\\">\\n            <we-button class=\\"fa fa-fw fa-square\\" data-select-class=\\"rounded\\" title=\\"Shape: Rounded\\"/>\\n            <we-button class=\\"fa fa-fw fa-circle-o\\" data-select-class=\\"rounded-circle\\" title=\\"Shape: Circle\\"/>\\n            <we-button class=\\"fa fa-fw fa-sun-o\\" data-select-class=\\"shadow\\" title=\\"Shadow\\"/>\\n            <we-button class=\\"fa fa-fw fa-picture-o\\" data-select-class=\\"img-thumbnail\\" title=\\"Shape: Thumbnail\\"/>\\n        </we-row>\\n\\n        <we-input string=\\"Padding\\" data-select-style=\\"\\" data-unit=\\"px\\" data-css-property=\\"padding\\"/>\\n    </div>\\n\\n    <div data-js=\\"DynamicSvg\\" data-selector=\\"img\\">\\n        <we-row string=\\"Dynamic Colors\\" data-name=\\"colors\\">\\n            <we-colorpicker data-color=\\"true\\" data-color-name=\\"c1\\"/>\\n            <we-colorpicker data-color=\\"true\\" data-color-name=\\"c2\\"/>\\n            <we-colorpicker data-color=\\"true\\" data-color-name=\\"c3\\"/>\\n            <we-colorpicker data-color=\\"true\\" data-color-name=\\"c4\\"/>\\n            <we-colorpicker data-color=\\"true\\" data-color-name=\\"c5\\"/>\\n        </we-row>\\n    </div>\\n</t>"}	<?xml version="1.0"?>\n<t t-name="web_editor.snippet_options">\n    <!-- t-field -->\n    <div data-js="many2one" data-selector="[data-oe-many2one-model]:not([data-oe-readonly])" data-no-check="true"/>\n\n    <div data-selector=".s_hr" data-drop-near="p, h1, h2, h3, blockquote, .s_hr"/>\n\n    <div data-js="VersionControl" data-selector="[data-snippet]"/>\n\n    <!-- Replace a media -->\n    <!-- TODO probably review this system once the new editor is merged to not duplicate the selector, etc -->\n    <div data-js="ReplaceMedia" data-selector="img, .media_iframe_video, span.fa, i.fa" data-exclude="[data-oe-xpath], a[href^='/website/social/'] &gt; i.fa, a[class*='s_share_'] &gt; i.fa">\n        <we-row string="Media">\n            <we-button class="o_we_bg_success" data-replace-media="true" data-no-preview="true">Replace</we-button>\n            <div>\n                <we-button class="fa fa-link" data-name="media_link_opt" data-set-link="true" data-no-preview="true" title="Redirect the user elsewhere when he clicks on the media."/>\n            </div>\n        </we-row>\n        <we-input string="Your URL" class="o_we_sublevel_1 o_we_large" data-name="media_url_opt" data-dependencies="media_link_opt" data-set-url="" data-no-preview="true" placeholder="www.example.com" data-request-focus="true"/>\n        <we-checkbox string="Open in new window" class="o_we_sublevel_1" data-dependencies="media_url_opt" data-set-new-window="true" data-no-preview="true"/>\n    </div>\n\n    <div data-js="FontawesomeTools" data-selector="span.fa, i.fa" data-exclude="[data-oe-xpath]">\n        <we-colorpicker string="Color" title="Color" data-select-style="" data-css-property="color" data-color-prefix="text-"/>\n\n        <we-colorpicker string="Background Color" title="Background Color" data-select-style="" data-css-property="background-color" data-color-prefix="bg-"/>\n\n        <we-button-group string="Size">\n            <we-button data-select-class="" title="Size 1x">1x</we-button>\n            <we-button data-select-class="fa-2x" title="Size 2x">2x</we-button>\n            <we-button data-select-class="fa-3x" title="Size 3x">3x</we-button>\n            <we-button data-select-class="fa-4x" title="Size 4x">4x</we-button>\n            <we-button data-select-class="fa-5x" title="Size 5x">5x</we-button>\n\n            <!-- Hidden buttons which allows to automatically remove other fa\n                 sizing class we do not suggest.\n                 TODO: implement a param to add those extra classes to remove\n                 via selectClass (also fixes the fact that nothing is selected\n                 if fa-1x is actually used on the icon in this case) -->\n            <we-button data-select-class="fa-1x" data-dependencies="fake"/>\n            <we-button data-select-class="fa-lg" data-dependencies="fake"/>\n        </we-button-group>\n    </div>\n\n    <t t-set="no_animations" t-value="False"/>\n    <div data-js="ImageTools" data-selector="img">\n        <div class="o_we_image_shape">\n            <we-row string="Shape" class="o_we_full_row">\n                <we-select-pager data-name="shape_img_opt" class="o_we_fake_transparent_background">\n                    <header class="o_pager_nav d-flex flex-column flex-wrap flex-shrink-0 mh-100">\n                        <div class="d-flex align-items-center">\n                            <button class="o_pager_nav_angle fa fa-angle-left btn btn-secondary bg-transparent border-0"/>\n                            <h5 class="o_pager_nav_title mb-0 text-white">Shapes</h5>\n                        </div>\n                        <div class="d-flex">\n                            <button type="button" class="o_pager_nav_btn p-0 text-uppercase active" data-scroll-to="o_scroll_shapes_basic">\n                                <span class="w-100">Basic</span>\n                            </button>\n                            <button type="button" class="o_pager_nav_btn p-0 text-uppercase" data-scroll-to="o_scroll_shapes_decorative">\n                                <span class="w-100">Decorative</span>\n                            </button>\n                            <button type="button" class="o_pager_nav_btn p-0 text-uppercase" data-scroll-to="o_scroll_shapes_devices">\n                                <span class="w-100">Devices</span>\n                            </button>\n                        </div>\n                    </header>\n                    <div class="o_pager_container">\n                        <div class="o_scroll_shapes_basic">\n                            <we-title class="">Geometrics</we-title>\n                            <we-select-page string="Geometrics">\n                                <we-button data-set-img-shape="web_editor/geometric/geo_square" data-no-transform="true" data-name="shape_img_square_opt"/> <!-- hidden and only used for hover effects -->\n                                <we-button data-set-img-shape="web_editor/geometric/geo_shuriken" data-select-label="Shuriken" data-no-transform="true"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_diamond" data-select-label="Diamond" data-no-transform="true"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_triangle" data-select-label="Triangle"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_cornered_triangle" data-select-label="Corner Triangle"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_pentagon" data-select-label="Pentagon"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_hexagon" data-select-label="Hexagon"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_heptagon" data-select-label="Heptagon"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_star" data-select-label="Star 1"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_star_8pin" data-select-label="Star 2" data-no-transform="true"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_star_16pin" data-select-label="Star 3" data-no-transform="true"/>\n                                <we-button data-set-img-shape="web_editor/geometric/geo_