 t-attf-id=\\"o_payment_token_{{token_sudo.id}}\\" name=\\"o_payment_radio\\" type=\\"radio\\" t-att-checked=\\"is_selected\\" t-att-disabled=\\"not allow_token_selection\\" t-att-class=\\"'form-check-input'                                             + (' d-none' if not allow_token_selection else '')\\" data-payment-option-type=\\"token\\" t-att-data-payment-option-id=\\"token_sudo.id\\" t-att-data-provider-code=\\"token_sudo.provider_id._get_code()\\" t-att-data-provider-id=\\"token_sudo.provider_id.id\\"/>\\n                        <div class=\\"d-flex align-items-center flex-wrap gap-2\\">\\n                            <!-- === Token label === -->\\n                            <label t-out=\\"token_sudo.payment_method_id.name\\" class=\\"o_payment_option_label text-break\\" t-attf-for=\\"o_payment_token_{{token_sudo.id}}\\"/>\\n                            <div class=\\"d-flex flex-nowrap gap-2\\">\\n                                <!-- === \\"Unpublished\\" icon === -->\\n                                <t t-if=\\"is_unpublished\\" t-call=\\"payment.form_icon\\">\\n                                    <t t-set=\\"icon_name\\" t-value=\\"'eye-slash'\\"/>\\n                                    <t t-set=\\"color_name\\" t-value=\\"'danger'\\"/>\\n                                    <t t-set=\\"title\\" t-value=\\"'Unpublished'\\"/>\\n                                </t>\\n                                <!-- === \\"Test mode\\" icon === -->\\n                                <t t-if=\\"is_test\\" t-call=\\"payment.form_icon\\">\\n                                    <t t-set=\\"icon_name\\" t-value=\\"'exclamation-triangle'\\"/>\\n                                    <t t-set=\\"color_name\\" t-value=\\"'warning'\\"/>\\n                                    <t t-set=\\"title\\" t-value=\\"'Test mode'\\"/>\\n                                </t>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- === Token name (payment details) === -->\\n                <div class=\\"col\\">\\n                    <p t-out=\\"token_sudo.display_name\\" t-att-class=\\"'mb-0 small fw-bold text-break'                                     + (' ms-4 ms-md-0' if allow_token_selection else '')\\"/>\\n                </div>\\n                <!-- === Provider name (only for desktop and tablet) === -->\\n                <div class=\\"col d-none d-md-block\\">\\n                    <p name=\\"o_payment_secured_by_desktop\\" t-att-class=\\"'mb-0 small text-600'                                     + (' ms-4 ms-md-0' if allow_token_selection else '')                                     + (' d-none' if provider_sudo.code == 'custom' else '')\\">\\n                        <span><i class=\\"fa fa-lock\\"/> Secured by</span>\\n                        <span t-out=\\"dict(provider_sudo._fields['code']._description_selection(                                          provider_sudo.env                                      ))[provider_sudo.code]\\" class=\\"text-break\\"/>\\n                    </p>\\n                </div>\\n            </div>\\n            <!-- === Payment method logo === -->\\n            <div t-call=\\"payment.form_logo\\">\\n                <t t-set=\\"logo_pm_sudo\\" t-value=\\"token_sudo.payment_method_id\\"/>\\n            </div>\\n        </div>\\n        <!-- === Inline form === -->\\n        <div t-if=\\"inline_form_xml_id\\" name=\\"o_payment_inline_form\\" class=\\"position-relative d-none\\">\\n            <t t-call=\\"{{inline_form_xml_id}}\\"/>\\n        </div>\\n        <!-- === Provider name (only for mobile) === -->\\n        <p name=\\"o_payment_secured_by_mobile\\" t-att-class=\\"'align-self-end d-block d-md-none mb-0 small text-600'                         + (' d-none' if provider_sudo.code == 'custom' else '')\\">\\n            <span><i class=\\"fa fa-lock\\"/> Secured by</span>\\n            <span t-out=\\"dict(provider_sudo._fields['code'].