620	16	\N	1	1	payment.transaction_status	\N	payment.transaction_status	qweb	payment/views/portal_templates.xml	primary	{"en_US": "<t t-name=\\"payment.transaction_status\\">\\n        <!-- Parameters description:\\n            - tx: The transaction whose status must be displayed.\\n        -->\\n        <t t-if=\\"tx.state == 'draft'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'info'\\"/>\\n            <t t-set=\\"status_message\\">\\n                <p>Your payment has not been processed yet.</p>\\n            </t>\\n        </t>\\n        <t t-elif=\\"tx.state == 'pending'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'warning'\\"/>\\n            <t t-set=\\"status_message\\" t-value=\\"tx.provider_id.sudo().pending_msg\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'authorized'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'success'\\"/>\\n            <t t-set=\\"status_message\\" t-value=\\"tx.provider_id.sudo().auth_msg\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'done'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'success'\\"/>\\n            <t t-set=\\"status_heading\\">Thank you!</t>\\n            <t t-set=\\"status_message\\" t-value=\\"tx.provider_id.sudo().done_msg\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'cancel'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'danger'\\"/>\\n            <t t-set=\\"status_message\\" t-value=\\"tx.provider_id.sudo().cancel_msg\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'error'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'danger'\\"/>\\n            <t t-set=\\"status_message\\">\\n                <p class=\\"mb-0\\">An error occurred during the processing of your payment.</p>\\n            </t>\\n        </t>\\n\\n        <t t-if=\\"is_html_empty(status_message)\\" t-set=\\"status_message\\" t-value=\\"''\\"/>\\n        <t t-set=\\"o_payment_status_alert_class\\" t-value=\\"'alert alert-'+ alert_style +' d-flex gap-3'\\"/>\\n\\n        <div t-if=\\"status_message or tx.state_message\\" name=\\"o_payment_status_alert\\" t-attf-class=\\"{{o_payment_status_alert_class}}\\">\\n            <div id=\\"o_payment_status_icon\\">\\n                <i t-attf-class=\\"fa fa-{{'check' if alert_style == 'success' else 'info-circle'                                  if alert_style == 'info' else 'exclamation-triangle'}}\\"/>\\n            </div>\\n            <div id=\\"o_payment_status_message\\" class=\\"w-100\\">\\n                <h5 t-if=\\"status_heading\\" t-out=\\"status_heading\\" class=\\"alert-heading mb-0\\"/>\\n                <t t-if=\\"status_message\\" t-out=\\"status_message\\" class=\\"mb-0\\"/>\\n                <t t-if=\\"tx.state_message\\" t-out=\\"tx.state_message\\" class=\\"mb-0\\"/>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.transaction_status">\n        <!-- Parameters description:\n            - tx: The transaction whose status must be displayed.\n        -->\n        <t t-if="tx.state == 'draft'">\n            <t t-set="alert_style" t-value="'info'"/>\n            <t t-set="status_message">\n                <p>Your payment has not been processed yet.</p>\n            </t>\n        </t>\n        <t t-elif="tx.state == 'pending'">\n            <t t-set="alert_style" t-value="'warning'"/>\n            <t t-set="status_message" t-value="tx.provider_id.sudo().pending_msg"/>\n        </t>\n        <t t-elif="tx.state == 'authorized'">\n            <t t-set="alert_style" t-value="'success'"/>\n            <t t-set="status_message" t-value="tx.provider_id.sudo().auth_msg"/>\n        </t>\n        <t t-elif="tx.state == 'done'">\n            <t t-set="alert_style" t-value="'success'"/>\n            <t t-set="status_heading">Thank you!</t>\n            <t t-set="status_message" t-value="tx.provider_id.sudo().done_msg"/>\n        </t>\n        <t t-elif="tx.state == 'cancel'">\n            <t t-set="alert_style" t-value="'danger'"/>\n            <t t-set="status_message" t-value="tx.provider_id.sudo().cancel_msg"/>\n        </t>\n        <t t-elif="tx.state == 'error'">\n            <t t-set="alert_style" t-value="'danger'"/>\n            <t t-set="status_message">\n                <p class="mb-0">An error occurred during the processing of your payment.</p>\n            </t>\n        </t>\n\n        <t t-if="is_html_empty(status_message)" t-set="status_message" t-value="''"/>\n        <t t-set="o_payment_status_alert_class" t-value="'alert alert-'+ alert_style +' d-flex gap-3'"/>\n\n        <div t-if="status_message or tx.state_message" name="o_payment_status_alert" t-attf-class="{{o_payment_status_alert_class}}">\n            <div id="o_payment_status_icon">\n                <i t-attf-class="fa fa-{{'check' if alert_style == 'success' else 'info-circle'                                  if alert_style == 'info' else 'exclamation-triangle'}}"/>\n            </div>\n            <div id="o_payment_status_message" class="w-100">\n                <h5 t-if="status_heading" t-out="status_heading" class="alert-heading mb-0"/>\n                <t t-if="status_message" t-out="status_message" class="mb-0"/>\n                <t t-if="tx.state_message" t-out="tx.state_message" class="mb-0"/>\n            </div>\n        </div>\n    </t>\n\n    	f	t	2026-09-17 09:18:19.306081	2026-09-17 09:18:19.306081	f
