e=\\"company_id\\" groups=\\"base.group_multi_company\\"/>\\n                    <filter string=\\"Customer/Vendor\\" name=\\"partner\\" domain=\\"[]\\" context=\\"{'group_by': 'partner_id'}\\"/>\\n                    <filter string=\\"Journal\\" name=\\"journal\\" domain=\\"[]\\" context=\\"{'group_by': 'journal_id'}\\"/>\\n                    <filter string=\\"Payment Method Line\\" name=\\"paymentmethodline\\" domain=\\"[]\\" context=\\"{'group_by': 'payment_method_line_id'}\\"/>\\n                    <filter string=\\"Status\\" name=\\"state\\" domain=\\"[]\\" context=\\"{'group_by': 'state'}\\"/>\\n                    <filter string=\\"Payment Date\\" name=\\"groupby_date\\" domain=\\"[]\\" context=\\"{'group_by': 'date'}\\"/>\\n                    <filter string=\\"Currency\\" name=\\"currency\\" domain=\\"[]\\" context=\\"{'group_by': 'currency_id'}\\" groups=\\"base.group_multi_currency\\"/>\\n                    <filter string=\\"Company\\" name=\\"company\\" domain=\\"[]\\" context=\\"{'group_by': 'company_id'}\\" groups=\\"base.group_multi_company\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" string=\\"Late Activities\\" name=\\"activities_overdue\\" domain=\\"[('my_activity_date_deadline', '&lt;', context_today().strftime('%Y-%m-%d'))]\\" help=\\"Show all records which has next action date is before today\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Today Activities\\" name=\\"activities_today\\" domain=\\"[('my_activity_date_deadline', '=', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Future Activities\\" name=\\"activities_upcoming_all\\" domain=\\"[('my_activity_date_deadline', '&gt;', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                </search>"}	<?xml version="1.0"?>\n<search string="Payments">\n                    <field name="name" string="Payment" filter_domain="['|', '|', '|', '|', ('name', 'ilike', self), ('partner_id'